def get_nested_dict_value(d, keys, default=None):
    """
    Retrieves a nested dictionary value with a default value if the path to the value is not found.

    :param d: The dictionary to search in.
    :param keys: A list of keys representing the path to the value.
    :param default: The default value to return if the path is not found.
    :return: The value at the given path, or the default value if the path is not found.
    """
    current = d
    for key in keys:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            return default
    return current

# Example usage:
my_dict = {
    'a': {
        'b': {
            'c': 'value'
        }
    }
}

print(get_nested_dict_value(my_dict, ['a', 'b', 'c']))  # Output: 'value'
print(get_nested_dict_value(my_dict, ['a', 'b', 'd'], 'Not Found'))  # Output: 'Not Found'
```

